
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_2d_js17_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_2d_js17", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.680411790987915e-01, -8.677736329526472e-01, -8.673539123802712e-01, -8.667091001181291e-01, -8.657509534231388e-01, -8.644009291635162e-01, -8.626565358337785e-01, -8.607198100584907e-01, -8.591705358613629e-01, -8.589856474760778e-01, -8.605092538133963e-01, -8.586561400570770e-01, -8.333255209562255e-01, -7.575624747254899e-01, -6.356613757916902e-01, -5.448144439266165e-01, -6.779359183603993e-01, -1.234728282134909e+00, -2.941219742255969e+00, -1.004789876605428e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


